hintProportionalAssignedWork: "Přidělená práce je uzamčena&#44 protože bude vypočítána (je povolen podílový režim).&#13 [přidělená práce] = [zbývající práce]&#13 Pokud již byl úkol spuštěn&#44 přidělená práce již není aktualizována.",
hintProportionalLeftWork: "Zbývající práce je uzamčena&#44 protože bude vypočítána (je aktivován podílový režim)&#13 [zbývající práce] = [doba trvání] x [míra přidělení]&# 13 Pro týmy&#13 [zbývající práce] = [doba trvání] x [míra přidělení] x [FTE]&#13 Doba trvání se počítá jako počet dní dostupných v kalendáři zdroje během trvání úkolu.&#13 Pokud byl úkol zahájen&#44 bere se v úvahu pouze zbývající doba trvání od dnešního dne.&#13",
hintSortOrderRelevance: "třídění zdrojů pro konkrétní hierarchickou úroveň dovedností v závislosti na důležitosti zdroje.",
hintVoteComment: "Váš komentář se uloží jako poznámka k položce.<br/>Může obsahovat informace o tom jak chcete aby se s položkou zacházelo (vyjádření potřeby nebo specifikace)..",
