minimumThresholdAssignError: "Přiřazená kapacita zdroje (s přihlédnutím k míře přidělení) nesmí být nižší než minimální denní povolená hodnota ${1}",
minimumThresholdInputError: "Minimální hodnota nesmí přesáhnout minimální přidělenou kapacitu zdroje. ${1}",
minute: "minuta",
