startGuideActionCreate: "Vytvořte několik",
startGuideActionMenu: "Definice prvních prvků",
startGuideActivity: "Činnosti jsou úkoly naplánované na vašich projektech. <br/>Můžete vytvořit strukturu rozpisu prací pro své projekty. <br/>Úrovně této struktury ve fázích / podfázích / úkolech / dílčích úkolech nejsou omezeny ...",
startGuideAffectation: "Aby bylo možné zobrazit položky projektu <br/>musí být k němu přiřazen prostředek.<br/>Přiřazení k projektu automaticky zviditelňuje položky jeho podprojektů.",
startGuideClient: "Zákazníci jsou subjekty pro které pracujete.<br/> Mohou být interní nebo externí.",
startGuideContact: "Kontakty jsou osoby se kterými jste v kontaktu prostřednictvím vašich klientských subjektů.",
startGuideFooter: "Zde jsou uvedeny hlavní funkce <br/>Jakmile se s těmito funkcemi seznámíte budete moci objevit další (četné) moduly schopné pokrýt správu vašich projektů.",
startGuideImputation: "Zdroje zadávají svou skutečnou práci na obrazovce pracovního výkazu den po dni a činnost po činnosti.<br/> Přehodnocení zbývající práce umožňuje aktualizovat plánování projektu s reálným pokrokem.",
startGuideIntro: "Zde je krátký návod který vám usnadní první kroky s nástrojem ELMONTA PROJEKTY<br/> Při konfiguraci prvních položek postupujte podle následujících kroků.<br/> Neváhejte stisknout [F1] a dostanete se do uživatelské příručky kde najdete další nápovědu.<br/> Návrat na &#34Start guide&#34 menu se vrátí sem.",
startGuideMilestone: "Milníky jsou klíčová data projektů.<br/>Můžete v nich definovat příchozí (pevné milníky) nebo výstupy (pohyblivé milníky).",
startGuidePlanning: "Plánování navrhuje Ganttovo zobrazení.<br/>Abyste mohli plánovat činnosti musíte k nim přiřadit zdroje a definovat práci kterou je třeba vykonat protože plánování se řídí prací.<br/>Pak můžete definovat vztahy mezi úkoly (předcházející odkazy) a milníky...<br/>Poté můžete provést plánovací výpočty s přihlédnutím ke všem omezením zdrojů jako je dostupnost.",
startGuideProject: "Projekt je hlavní položkou v ELMONTA PROJEKTY<br/>Každá položka je propojena s projektem.<br/>Přístupová práva jsou definována rovněž na úrovni projektu.",
startGuideResource: "Zdroje jsou osoby nebo stroje které budou na úkolech pracovat.<br/>Pokud zaškrtnete « je uživatel » bude se moci zdroj (pokud je to osoba) připojit k ELMONTA PROJEKTY.",
startGuideTicket: "Tikety umožňují sledovat každou aktuální událost spojenou s projektem<br/> jako jsou chyby nebo jakýkoli požadavek.<br/>V případě potřeby je lze snadno zkopírovat do aktivit aniž by bylo nutné znovu zadávat údaje a udržovat je propojené s původním požadavkem.",
startGuideTitle: "Úvodní nástěnka",
startGuideUser: "Uživatelé jsou osoby které se mohou k aplikaci připojit.<br/>Musí mít profil který určuje přístupová práva k příslušným funkcím.",
