tooltipFixPlanningActivity: "Pokud má činnost &#34fixní plánování&#34 nikdy se nepřepočítává<br/>To znamená že plánování bude vždy stejné ať děláte na jiných projektech cokoli<br/>Toto může vést k nekonzistenci vazeb.",
