tooltipMinimumThreshold: "Minimální denní limit pro plánování. <br/> Činnost bude na daný den naplánována pouze tehdy pokud je denní dostupnost vyšší nebo rovna této minimální hodnotě.",
tooltipNotifiable: "Zvolte prvek který podléhá oznamovací povinnosti a na jehož základě se vytvoří pravidlo pro generování oznámení",
tooltipNotificationDaysBefore: "Počet dní před referenčním datem pro které se mají generovat oznámení. <br/> Například předběžné oznámení = 10 - Denní = Vybrané <br/> Oznámení bude vydáváno denně počínaje 10 dny před referenčním datem. <br/>Pokud je záporné => Generování oznámení začne až PO referenčním datu.",
tooltipNotificationEveryDay: "Pokud je vybráno <br/> budou se každý pracovní den generovat příslušná upozornění",
tooltipNotificationEveryMonth: "Pokud je vybráno<br/>Upozornění odpovídající pravidlu se budou generovat každý měsíc",
