tooltipNotificationGenerateBefore: "Oznámení bude vygenerováno o tento počet dní dříve než je skutečné vypočítané datum oznámení.",
tooltipNotificationGenerateBeforeInMin: "Aktivovat pouze v případě že referenční datum je datum a čas<br/>Upozornění bude generováno o tento počet minut dříve než je skutečný čas vypočítaného data upozornění.",
tooltipNotificationMenu: "Zvolte oznamovaný prvek na webu a přečtěte si pravidlo pro generování oznámení",
tooltipNotificationNbRepeatsBefore: "Počet případů před referenčním datem pro které se mají generovat oznámení. <br/> Např. kolikrát = 2 - Týdně = Vybráno <br/> Oznámení bude zasláno týdně počínaje 2 týdny před referenčním datem. <br/>Pokud je záporné => Generování oznámení začne až po referenčním datu se zvolenou frekvencí pokud je pravidlo v pořádku.",
tooltipNotificationReceivers: "Příjemci generovaného oznámení.<br/>Seznam příjemců oddělených čárkou.Např. idUser;idContact.Seznam povolených příjemců v &#34;Nápověda - Povolení příjemci&#34;",
